```tsx
import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
  onReset?: () => void;
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const stack = info.componentStack ?? null;
    console.error("[ErrorBoundary]", {
      timestamp: new Date().toISOString(),
      message: error.message,
      stack: error.stack,
      componentStack: stack,
    });
    this.props.onError?.(error, info);
    this.setState({ componentStack: stack });
  }

  reset = (): void => {
    this.props.onReset?.();
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error } = this.state;

    if (error) {
      if (this.props.fallback) return this.props.fallback;

      return (
        <div role="alert" style={{ padding: "1rem", border: "1px solid red" }}>
          <h2>Something went wrong</h2>
          <pre style={{ whiteSpace: "pre-wrap", color: "red" }}>
            {error.message}
          </pre>
          <button onClick={this.reset}>Try Again</button>
        </div>
      );
    }

    return this.props.children;
  }
}
```

**Changes from existing file:**

| Added | Why |
|-------|-----|
| `onError` prop | Custom log sink (Sentry, Datadog, etc.) |
| `onReset` prop | Caller hook for state cleanup before retry |
| Structured log object | `timestamp` + `stack` + `componentStack` all in one `console.error` call |

**Usage:**
```tsx
<ErrorBoundary
  onError={(err, info) => Sentry.captureException(err, { extra: info })}
  onReset={() => queryClient.clear()}
>
  <MyComponent />
</ErrorBoundary>
```

`reset()` clears state → React retries render from scratch. `fallback` prop overrides default UI when custom error screen needed.

